import{_ as l,a0 as r,w as d,s as o,ao as p,I as n,x as s,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"什麼是 Git 遴選（cherry-pick）？ | LCTT x X-CMD","titleTemplate":false,"description":"什麼是 Git 遴選（cherry-pick）？ | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什麼是 Git 遴選（cherry-pick）？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什麼是 Git 遴選（cherry-pick）？ | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210407 What is Git cherry-picking","title":"什麼是 Git 遴選（cherry-pick）？","tag":"202104","desc":""},"relativePath":"202104/20210407 What is Git cherry-picking.md","filePath":"[post].md"}'),h={name:"202104/20210407 What is Git cherry-picking.md"};function g(c,i,k,u,b,f){const e=r("Link");return d(),o("div",null,[i[25]||(i[25]=p('<h1 id="什麼是-git-遴選-cherry-pick" tabindex="-1">什麼是 Git 遴選（cherry-pick）？ <a class="header-anchor" href="#什麼是-git-遴選-cherry-pick" aria-label="Permalink to “什麼是 Git 遴選（cherry-pick）？”">​</a></h1><blockquote><p>瞭解 <code>git cherry-pick</code> 命令是什麼，為什麼用以及如何使用。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202104/14/131735o63v3ow6y2wc281o.jpg" alt=""></p><p>當你和一羣程序員一起工作時，無論項目大小，處理多個 Git 分支之間的變更都會變得很困難。有時，你不想將整個 Git 分支合併到另一個分支，而是想選擇並移動幾個特定的提交。這個過程被稱為 “<ruby>遴選<rt>cherry-pick</rt></ruby>”。</p><p>本文將介紹“遴選”是什麼、為何使用以及如何使用。</p><p>那麼讓我們開始吧。</p><h3 id="什麼是遴選" tabindex="-1">什麼是遴選？ <a class="header-anchor" href="#什麼是遴選" aria-label="Permalink to “什麼是遴選？”">​</a></h3>',7)),n("p",null,[i[1]||(i[1]=s("使用遴選（",-1)),i[2]||(i[2]=n("code",null,"cherry-pick",-1)),i[3]||(i[3]=s("）命令，Git 可以讓你將任何分支中的個別提交合併到你當前的 ",-1)),t(e,{href:"https://acompiler.com/git-head/"},{default:a(()=>[...i[0]||(i[0]=[s("Git HEAD",-1)])]),_:1}),i[4]||(i[4]=s(" 分支中。",-1))]),i[26]||(i[26]=p('<p>當執行 <code>git merge</code> 或者 <code>git rebase</code> 時，一個分支的所有提交都會被合併。<code>cherry-pick</code> 命令允許你選擇單個提交進行整合。</p><h3 id="遴選的好處" tabindex="-1">遴選的好處 <a class="header-anchor" href="#遴選的好處" aria-label="Permalink to “遴選的好處”">​</a></h3><p>下面的情況可能會讓你更容易理解遴選功能。</p><p>想像一下，你正在為即將到來的每週衝刺實現新功能。當你的代碼準備好了，你會把它推送到遠程分支，準備進行測試。</p><p>然而，客户並不是對所有修改都滿意，要求你只呈現某些修改。因為客户還沒有批准下次發佈的所有修改，所以 <code>git rebase</code> 不會有預期的結果。為什麼會這樣？因為 <code>git rebase</code> 或者 <code>git merge</code> 會把上一個衝刺的每一個調整都納入其中。</p><p>遴選就是答案！因為它只關注在提交中添加的變更，所以遴選只會帶入批准的變更，而不添加其他的提交。</p><p>還有其他幾個原因可以使用遴選：</p><ul><li>這對於 bug 修復是必不可少的，因為 bug 是出現在開發分支中對應的提交的。</li><li>你可以通過使用 <code>git cherry-pick</code> 來避免不必要的工作，而不用使用其他選項例如 <code>git diff</code> 來應用特定變更。</li><li>如果因為不同 Git 分支的版本不兼容而無法將整個分支聯合起來，那麼它是一個很有用的工具。</li></ul><h3 id="使用-cherry-pick-命令" tabindex="-1">使用 cherry-pick 命令 <a class="header-anchor" href="#使用-cherry-pick-命令" aria-label="Permalink to “使用 cherry-pick 命令”">​</a></h3>',9)),n("p",null,[i[6]||(i[6]=s("在 ",-1)),i[7]||(i[7]=n("code",null,"cherry-pick",-1)),i[8]||(i[8]=s(" 命令的最簡單形式中，你只需使用 ",-1)),t(e,{href:"https://en.wikipedia.org/wiki/Secure_Hash_Algorithms"},{default:a(()=>[...i[5]||(i[5]=[s("SHA",-1)])]),_:1}),i[9]||(i[9]=s(" 標識符來表示你想整合到當前 HEAD 分支的提交。",-1))]),i[27]||(i[27]=p(`<p>要獲得提交的哈希值，可以使用 <code>git log</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log --oneline</span></span></code></pre></div><p>當你知道了提交的哈希值後，你就可以使用 <code>cherry-pick</code> 命令。</p><p>語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cherry-pick &lt;commit sha&gt;</span></span></code></pre></div><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cherry-pick 65be1e5</span></span></code></pre></div><p>這將會把指定的修改合併到當前已簽出的分支上。</p><p>如果你想做進一步的修改，也可以讓 Git 將提交的變更內容添加到你的工作副本中。</p><p>語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cherry-pick &lt;commit sha&gt; --no-commit</span></span></code></pre></div><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cherry-pick 65be1e5 --no-commit</span></span></code></pre></div><p>如果你想同時選擇多個提交，請將它們的提交哈希值用空格隔開：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cherry-pick hash1 hash3</span></span></code></pre></div><p>當遴選提交時，你不能使用 <code>git pull</code> 命令，因為它能獲取一個倉庫的提交<strong>並</strong>自動合併到另一個倉庫。<code>cherry-pick</code> 是一個專門不這麼做的工具；另一方面，你可以使用 <code>git fetch</code>，它可以獲取提交，但不應用它們。毫無疑問，<code>git pull</code> 很方便，但它不精確。</p><h3 id="自己嘗試" tabindex="-1">自己嘗試 <a class="header-anchor" href="#自己嘗試" aria-label="Permalink to “自己嘗試”">​</a></h3><p>要嘗試這個過程，啓動終端並生成一個示例項目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir fruit.git</span></span>
<span class="line"><span>$ cd fruit.git</span></span>
<span class="line"><span>$ git init .</span></span></code></pre></div><p>創建一些數據並提交：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Kiwifruit&quot; &gt; fruit.txt</span></span>
<span class="line"><span>$ git add fruit.txt</span></span>
<span class="line"><span>$ git commit -m &#39;First commit&#39;</span></span></code></pre></div><p>現在，通過創建一個項目的復刻來代表一個遠程開發者：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/fruit.fork</span></span>
<span class="line"><span>$ cd !$</span></span>
<span class="line"><span>$ echo &quot;Strawberry&quot; &gt;&gt; fruit.txt</span></span>
<span class="line"><span>$ git add fruit.txt</span></span>
<span class="line"><span>$ git commit -m &#39;Added a fruit&quot;</span></span></code></pre></div><p>這是一個有效的提交。現在，創建一個不好的提交，代表你不想合併到你的項目中的東西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;Rhubarb&quot; &gt;&gt; fruit.txt</span></span>
<span class="line"><span>$ git add fruit.txt</span></span>
<span class="line"><span>$ git commit -m &#39;Added a vegetable that tastes like a fruit&quot;</span></span></code></pre></div><p>返回你的倉庫，從你的假想的開發者那裏獲取提交的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/fruit.git</span></span>
<span class="line"><span>$ git remote add dev ~/fruit.fork</span></span>
<span class="line"><span>$ git fetch dev</span></span>
<span class="line"><span>remote: Counting objects: 6, done.</span></span>
<span class="line"><span>remote: Compressing objects: 100% (2/2), done.</span></span>
<span class="line"><span>remote: Total 6 (delta 0), reused 0 (delta 0)</span></span>
<span class="line"><span>Unpacking objects: 100% (6/6), done...</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git log –oneline dev/master</span></span>
<span class="line"><span>e858ab2 Added a vegetable that tastes like a fruit</span></span>
<span class="line"><span>0664292 Added a fruit</span></span>
<span class="line"><span>b56e0f8 First commit</span></span></code></pre></div><p>你已經從你想像中的開發者那裏獲取了提交的內容，但你還沒有將它們合併到你的版本庫中。你想接受第二個提交，但不想接受第三個提交，所以使用 <code>cherry-pick</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cherry-pick 0664292</span></span></code></pre></div><p>第二次提交現在在你的倉庫裏了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat fruit.txt</span></span>
<span class="line"><span>Kiwifruit</span></span>
<span class="line"><span>Strawberry</span></span></code></pre></div><p>將你的更改推送到遠程服務器上，這就完成了！</p><h3 id="避免使用遴選的原因" tabindex="-1">避免使用遴選的原因 <a class="header-anchor" href="#避免使用遴選的原因" aria-label="Permalink to “避免使用遴選的原因”">​</a></h3><p>在開發者社區中，通常不鼓勵所以遴選。主要原因是它會造成重複提交，而你也失去了跟蹤你的提交歷史的能力。</p><p>如果你不按順序地遴選了大量的提交，這些提交會被記錄在你的分支中，這可能會在 Git 分支中導致不理想的結果。</p><p>遴選是一個強大的命令，如果沒有正確理解可能發生的情況，它可能會導致問題。不過，當你搞砸了，提交到錯誤的分支時，它可能會救你一命（至少是你當天的工作）。</p><hr>`,38)),n("p",null,[i[11]||(i[11]=s("via: ",-1)),t(e,{href:"https://opensource.com/article/21/4/cherry-picking-git"},{default:a(()=>[...i[10]||(i[10]=[s("https://opensource.com/article/21/4/cherry-picking-git",-1)])]),_:1})]),n("p",null,[i[16]||(i[16]=s("作者：",-1)),t(e,{href:"https://opensource.com/users/acompiler"},{default:a(()=>[...i[12]||(i[12]=[s("Rajeev Bera",-1)])]),_:1}),i[17]||(i[17]=s(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[13]||(i[13]=[s("lujun9972",-1)])]),_:1}),i[18]||(i[18]=s(" 譯者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:a(()=>[...i[14]||(i[14]=[s("geekpi",-1)])]),_:1}),i[19]||(i[19]=s(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...i[15]||(i[15]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[22]||(i[22]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[20]||(i[20]=[s("LCTT",-1)])]),_:1}),i[23]||(i[23]=s(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...i[21]||(i[21]=[s("Linux中國",-1)])]),_:1}),i[24]||(i[24]=s(" 榮譽推出",-1))])])}const x=l(h,[["render",g]]);export{C as __pageData,x as default};
